import React, { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";

export default function Home({
  token,
  onLogout,
  onShowDeposit,
  onShowWithdraw,
  onShowAdminWithdraw,
  onShowAdminDepositRequests,
  onShowHistory,
  onShowAdminUserHistory,
  onShowLudoMatch,
}) {
  const navigate = useNavigate();
  const [balance, setBalance] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [userProfile, setUserProfile] = useState(null);
  const [editing, setEditing] = useState(false);
  const [displayName, setDisplayName] = useState("");
  const [avatarFile, setAvatarFile] = useState(null);
  const fileInputRef = useRef();

  useEffect(() => {
    if (!token) return;
    const fetchUserData = async () => {
      try {
        const res = await fetch("http://localhost:8080/api/user/profile", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error("Failed to fetch user profile");
        const data = await res.json();
        setUserProfile(data);
        setDisplayName(data.displayName || "");
        setIsAdmin(data.role?.toLowerCase() === "admin");
      } catch (err) {
        console.error("Failed to get user profile:", err);
      }
    };
    fetchUserData();
  }, [token]);

  useEffect(() => {
    if (!token) return;
    const fetchBalance = async () => {
      try {
        const res = await fetch("http://localhost:8080/api/user/balance", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json();
        if (res.ok && data.balance != null && !isNaN(data.balance)) {
          setBalance(parseFloat(data.balance));
        } else {
          throw new Error("Invalid balance response");
        }
      } catch (error) {
        console.error("Failed to fetch balance:", error);
        setBalance("Error");
      } finally {
        setLoading(false);
      }
    };
    fetchBalance();
  }, [token]);

  const renderBalance = () => {
    if (loading)
      return <span className="text-gray-400">Loading...</span>;
    if (balance === "Error")
      return <span className="text-red-500">Balance unavailable</span>;
    return (
      <span className="text-3xl font-semibold text-green-600">
        ৳ {balance.toFixed(2)}
      </span>
    );
  };

  const handleSaveProfile = async () => {
    try {
      const updateRes = await fetch("http://localhost:8080/api/user/profile", {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ displayName }),
      });

      if (!updateRes.ok) throw new Error("Failed to update profile");

      let avatarUrl = userProfile.avatarUrl;

      if (avatarFile) {
        const formData = new FormData();
        formData.append("file", avatarFile);

        const avatarRes = await fetch("http://localhost:8080/api/user/avatar", {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: formData,
        });

        if (!avatarRes.ok) throw new Error("Failed to upload avatar");
        const data = await avatarRes.json();
        avatarUrl = data.avatarUrl;
      }

      // If avatar was removed (avatarUrl null), keep it null
      setUserProfile((prev) => ({
        ...prev,
        displayName,
        avatarUrl,
      }));

      alert("✅ Profile updated successfully.");
      setEditing(false);
      setAvatarFile(null);
    } catch (err) {
      console.error(err);
      alert("❌ Failed to update profile.");
    }
  };

  const handleRemoveAvatar = async () => {
    try {
      const res = await fetch("http://localhost:8080/api/user/avatar", {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to remove avatar");

      setUserProfile((prev) => ({
        ...prev,
        avatarUrl: null,
      }));

      // Also clear any avatar file currently selected for upload
      setAvatarFile(null);

      alert("🗑️ Avatar removed.");
    } catch (err) {
      console.error(err);
      alert("❌ Failed to remove avatar");
    }
  };

  const renderAvatar = () => {
    if (avatarFile) return URL.createObjectURL(avatarFile);
    if (userProfile?.avatarUrl)
      return `http://localhost:8080${userProfile.avatarUrl}`;
    return `https://ui-avatars.com/api/?name=${encodeURIComponent(
      userProfile?.displayName || "U"
    )}&background=0D8ABC&color=fff&size=128`;
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans">
      {/* Header */}
      <header className="bg-white shadow-md py-4 px-8 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
          🎮 Ludo Dashboard
        </h1>
        <button
          onClick={onLogout}
          className="bg-red-600 hover:bg-red-700 text-white px-5 py-2 rounded-md font-semibold transition"
          aria-label="Logout"
        >
          🚪 Logout
        </button>
      </header>

      {/* Main Content */}
      <main className="max-w-4xl mx-auto mt-12 px-4">
        {/* Balance Card */}
        <section className="bg-white rounded-lg shadow p-6 flex items-center justify-between mb-10">
          <div>
            <p className="text-gray-600 font-medium uppercase tracking-wide">
              Current Balance
            </p>
            {renderBalance()}
          </div>
          <img
            src="https://cdn-icons-png.flaticon.com/512/1170/1170576.png"
            alt="Wallet Icon"
            className="w-14 h-14 opacity-60"
          />
        </section>

        {/* Profile Card */}
        <section className="bg-white rounded-lg shadow p-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-semibold text-gray-800">User Profile</h2>
            {!editing ? (
              <button
                onClick={() => setEditing(true)}
                className="text-indigo-600 hover:text-indigo-800 font-medium transition"
                aria-label="Edit Profile"
              >
                ✏️ Edit Profile
              </button>
            ) : (
              <div className="flex gap-4">
                <button
                  onClick={handleSaveProfile}
                  className="text-green-600 font-semibold hover:text-green-800 transition"
                  aria-label="Save Profile"
                >
                  ✅ Save
                </button>
                <button
                  onClick={() => {
                    setEditing(false);
                    setAvatarFile(null);
                    setDisplayName(userProfile.displayName || "");
                  }}
                  className="text-gray-500 hover:text-gray-700 transition"
                  aria-label="Cancel Edit"
                >
                  ❌ Cancel
                </button>
              </div>
            )}
          </div>

          <div className="flex flex-col sm:flex-row items-center gap-8">
            <div className="relative">
              <img
                src={renderAvatar()}
                alt="User Avatar"
                className="w-32 h-32 rounded-full border border-gray-300 object-cover shadow-sm"
              />
              {editing && (
                <>
                  <div
                    className="absolute bottom-0 right-0 bg-indigo-600 rounded-full p-2 cursor-pointer hover:bg-indigo-700 transition"
                    onClick={() => fileInputRef.current.click()}
                    title="Change Avatar"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      className="h-5 w-5 text-white"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                  </div>
                  {userProfile?.avatarUrl && (
                    <button
                      onClick={handleRemoveAvatar}
                      className="mt-2 text-sm text-red-600 hover:underline"
                      title="Remove Avatar"
                    >
                      🗑️ Remove Avatar
                    </button>
                  )}
                </>
              )}
              <input
                type="file"
                accept="image/*"
                onChange={(e) => setAvatarFile(e.target.files[0])}
                ref={fileInputRef}
                className="hidden"
              />
            </div>

            <div className="flex-1 w-full max-w-md space-y-4 text-gray-700">
              <div>
                <label
                  className="block font-medium mb-1"
                  htmlFor="displayName"
                >
                  👤 Display Name
                </label>
                {editing ? (
                  <input
                    id="displayName"
                    type="text"
                    value={displayName}
                    onChange={(e) => setDisplayName(e.target.value)}
                    className="w-full rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  />
                ) : (
                  <p className="text-lg font-semibold">
                    {userProfile.displayName || "Not set"}
                  </p>
                )}
              </div>
            </div>
          </div>
        </section>

        {/* Action Buttons */}
        <section className="grid grid-cols-1 sm:grid-cols-2 gap-5 mt-10">
          <ActionButton
            text="💰 Deposit"
            onClick={onShowDeposit}
            className="bg-green-600 hover:bg-green-700"
          />
          <ActionButton
            text="💸 Withdraw"
            onClick={onShowWithdraw}
            className="bg-red-600 hover:bg-red-700"
          />
          <ActionButton
            text="📂 My Transaction History"
            onClick={onShowHistory}
            className="bg-cyan-600 hover:bg-cyan-700"
          />
          <ActionButton
            text="🎲 Play Ludo"
            onClick={onShowLudoMatch}
            className="bg-yellow-500 hover:bg-yellow-600"
          />
          {isAdmin && (
            <>
              <ActionButton
                text="📥 Admin Deposit Requests"
                onClick={onShowAdminDepositRequests}
                className="bg-purple-600 hover:bg-purple-700"
              />
              <ActionButton
                text="📤 Admin Withdraw Requests"
                onClick={onShowAdminWithdraw}
                className="bg-blue-600 hover:bg-blue-700"
              />
              <ActionButton
                text="🧾 All User History"
                onClick={onShowAdminUserHistory}
                className="bg-gray-700 hover:bg-gray-800"
              />
              <ActionButton
                text="⚙️ Admin Payment Number"
                onClick={() => navigate("/payment-number")}
                className="bg-orange-600 hover:bg-orange-700"
              />
            </>
          )}
        </section>
      </main>
    </div>
  );
}

function ActionButton({ text, onClick, className }) {
  return (
    <button
      onClick={onClick}
      className={`text-white font-semibold py-4 rounded-lg shadow-md transition duration-200 ${className}`}
    >
      {text}
    </button>
  );
}
